# Import of required libraries
import skyramp
import os
import time

from SkyrampUtils import create_user, create_application, update_application


# URL for test requests
URL_localhost = skyramp.get_base_url("SKYRAMP_TEST_BASE_URL", "http://localhost:8090")


def test_integration():
    # Invocation of Skyramp Client
    client = skyramp.Client()
    # Definition of authentication header
    headers = {}
    if os.getenv("SKYRAMP_TEST_TOKEN") is not None:
        headers["X-Gotify-Key"] = os.getenv("SKYRAMP_TEST_TOKEN")

    isolation_user_b_name = skyramp.unique_suffix("isolation_user_b")

    user_POST_response = create_user(
        client,
        headers,
        isolation_user_b_name,
    )

    assert skyramp.get_response_value(user_POST_response, "name") == isolation_user_b_name
    assert skyramp.get_response_value(user_POST_response, "admin") is False
    assert int(skyramp.get_response_value(user_POST_response, "id")) > 0

    application_POST_response = create_application(
        client,
        headers,
        "isolation-probe",
        "",
        0,
    )

    assert skyramp.get_response_value(application_POST_response, "name") == "isolation-probe"
    assert skyramp.get_response_value(application_POST_response, "description") == ""
    assert skyramp.get_response_value(application_POST_response, "defaultPriority") == 0
    assert skyramp.get_response_value(application_POST_response, "internal") is False
    assert skyramp.get_response_value(application_POST_response, "image") == "static/defaultapp.png"
    assert int(skyramp.get_response_value(application_POST_response, "id")) > 0
    assert skyramp.get_response_value(application_POST_response, "token") is not None

    application_999999_PUT_response = update_application(
        client,
        headers,
        999999,
        "hijacked",
        404,
    )

    assert skyramp.get_response_value(application_999999_PUT_response, "error") == "Not Found"
    assert skyramp.get_response_value(application_999999_PUT_response, "errorCode") == 404
    assert skyramp.get_response_value(application_999999_PUT_response, "errorDescription") == "app with id 999999 doesn't exists"


if __name__ == "__main__":
    test_integration()
